"""Check sealed completed JVMs against qualified query-ordinal routes; never read timing metrics."""
import argparse
import hashlib
import json
from pathlib import Path

RAW_FILES = {'launch.json', 'process.json', 'inputs-before.json', 'inputs-after.json',
             'console.log', 'samples.jsonl', 'gc.log', 'validation.json'}
ROUTE_COUNTERS = ('irPlanned', 'irOpened', 'irRows', 'semanticNativeCompiles', 'compiledBinds',
                  'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds',
                  'hostedGeneric', 'unhostedHardDeclines', 'chunkEngaged',
                  'leftJoinReplayMaterializations', 'factorizedEngagement')


def need(condition, message):
    if not condition:
        raise ValueError(message)


def read(path):
    return json.loads(path.read_text())


def sha(path):
    with path.open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def object_sha(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, allow_nan=False).encode()).hexdigest()


def route(sample):
    return {'selections': sample['successfulSelections'],
            'counters': {key: sample['counters'][key] for key in ROUTE_COUNTERS},
            'nativeProjectedRows': sample['nativeProjectedRows'], 'adjacency': sample['adjacency']}


def inspect(cohort, allow_incomplete):
    need(not (cohort / 'failure.json').exists(), 'Cohort has a permanent failure receipt')
    protocol_file = cohort / 'protocol.json'
    protocol_hash = sha(protocol_file)
    need(protocol_hash == (cohort / 'protocol.sha256').read_text().strip(), 'Protocol seal failed')
    protocol = read(protocol_file)
    need(protocol['format'] == 'rdf4j-phase-growth-comparison-v1'
         and protocol['cohort'] == str(cohort) and protocol['warmups'] == 8 and protocol['measurements'] == 5,
         'Wrong cohort or query sequence')
    qualification_file = Path(protocol['qualificationFile'])
    for path in (qualification_file, Path(__file__).resolve()):
        entries = [item for item in protocol['inputs'] if item['path'] == str(path)]
        need(len(entries) == 1 and entries[0]['kind'] == 'file'
             and entries[0]['sha256'] == sha(path) and entries[0]['bytes'] == path.stat().st_size,
             'Qualification/checker is not bound to these frozen bytes: ' + str(path))
    qualification = read(qualification_file)
    need(qualification['format'] == 'growth-final-runtime-qualification-v1'
         and qualification['qualifiedForTiming'] is True and qualification['exactOracleQualified'] is True
         and qualification['fixtureDefinitionsSha256'] == protocol['fixtureDefinitionsSha256']
         and qualification['runtimeInputsSha256'] == protocol['runtimeInputsSha256'], 'Qualification identity failed')
    profiles = qualification['qualifiedRouteProfiles']
    need(set(profiles) == set(protocol['fixtures'])
         and object_sha(profiles) == qualification['qualifiedRouteProfilesSha256']
         and all(len(profile) == 13 for profile in profiles.values()), 'Qualified route profile seal failed')
    claims = sorted((cohort / 'claims').iterdir())
    schedule = protocol['schedule']
    need(len(claims) <= len(schedule) and [p.name for p in claims] ==
         [f'{i:04d}.json' for i in range(len(claims))], 'Claims are not a contiguous prefix')
    need({p.name for p in cohort.glob('round-*')} ==
         {Path(s['directory']).name for s in schedule[:len(claims)]}, 'Unclaimed or missing run directory')
    need(allow_incomplete or len(claims) == len(schedule), 'Full cohort required')
    checked = []
    for slot, claim_file in zip(schedule, claims):
        folder = Path(slot['directory'])
        need(folder.parent == cohort, 'Run is outside cohort')
        seal_file = folder / 'completion.json'
        need(seal_file.is_file(), 'Claimed JVM is unsealed; no partial or in-progress slot is accepted')
        seal = read(seal_file)
        need(seal['ordinal'] == slot['ordinal'] and seal['protocolSha256'] == protocol_hash
             and seal['claimSha256'] == sha(claim_file) and set(seal['rawHashes']) == RAW_FILES,
             'Completion identity failed')
        need(all(sha(folder / name) == digest for name, digest in seal['rawHashes'].items()), 'Raw seal failed')
        process = read(folder / 'process.json')
        need(process['exitCode'] == 0 and process['failure'] is None, 'JVM did not complete normally')
        records = [json.loads(line) for line in (folder / 'samples.jsonl').read_text().splitlines()]
        need(len(records) == 15 and records[0]['type'] == 'metadata'
             and records[-1]['type'] == 'completion', 'Wrong record sequence')
        observed = []
        for index, sample in enumerate(records[1:-1]):
            need(sample['type'] == 'sample' and sample['arm'] == slot['arm']
                 and sample['iteration'] == index - 8
                 and sample['stage'] == ('warmup' if index < 8 else 'measurement'), 'Query ordinal changed')
            observed.append(route(sample))
            need(observed[-1] == profiles[slot['fixture']][index],
                 f"Qualified route differs: JVM {slot['ordinal']}, query {index}, fixture {slot['fixture']}")
        checked.append({'ordinal': slot['ordinal'], 'fixture': slot['fixture'], 'arm': slot['arm'],
                        'completionSha256': sha(seal_file), 'routeProfileSha256': object_sha(observed)})
    return {'passed': True, 'cohort': str(cohort), 'protocolSha256': protocol_hash,
            'qualificationSha256': sha(qualification_file), 'checkerSha256': sha(Path(__file__).resolve()),
            'qualifiedRouteProfilesSha256': object_sha(profiles), 'completedJvms': len(checked),
            'remainingJvms': len(schedule) - len(checked), 'queriesChecked': 13 * len(checked),
            'completeCohort': len(checked) == len(schedule), 'checked': checked,
            'scope': 'Same-ordinal native route and adjacency profile only; excludes source/materialization outcomes.',
            'timingOrAllocationAnalysisPerformed': False}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cohort', required=True, type=Path)
    parser.add_argument('--output', required=True, type=Path)
    parser.add_argument('--allow-incomplete', action='store_true')
    args = parser.parse_args()
    need(not args.output.exists(), 'Output must be a fresh file')
    try:
        result = inspect(args.cohort.resolve(), args.allow_incomplete)
    except Exception as error:
        result = {'passed': False, 'failure': str(error), 'cohort': str(args.cohort.resolve()),
                  'timingOrAllocationAnalysisPerformed': False}
    args.output.parent.mkdir(parents=True, exist_ok=True)
    with args.output.open('x') as stream:
        stream.write(json.dumps(result, sort_keys=True, indent=2) + '\n')
    print(json.dumps({key: value for key, value in result.items() if key != 'checked'}))
    raise SystemExit(0 if result['passed'] else 1)


if __name__ == '__main__':
    main()
